 { id: "madb6", topic: "mad-coll", q: "Was gibt der Code aus?", code: "val ects = mutableMapOf(\"INFO2\" to 5.0, \"SWENGB\" to 5.0)\nects[\"DMT3\"] = 2.5\nects[\"INFO2\"] = 6.0\nprintln(ects.size.toString() + \" \" + ects.values.sum())", opts: ["4 18.5", "3 13.5", "3 12.5", "3 16.0"], a: 1, why: "INFO2 wird überschrieben (Keys eindeutig): 6.0 + 5.0 + 2.5 = 13.5, 3 Einträge.", ex: "" },
 { id: "madb7", topic: "mad-inh", q: "Was gibt der Code aus?", code: "open class A { open fun f() = \"A\"; fun g() = \"g\" + f() }\nclass B : A() { override fun f() = \"B\" }\nval x: A = B()\nprintln(x.g())", opts: ["gA", "gB", "Compilerfehler", "AB"], a: 1, why: "g() ruft f() auf – durch dynamic dispatch die überschriebene Version aus B.", ex: "" },
 { id: "madb8", topic: "mad-data", q: "Was gibt der Code aus?", code: "data class P(val x: Int, val y: Int)\nval set = setOf(P(1, 2), P(1, 2), P(2, 1))\nval (a, b) = P(3, 4)\nprintln(\"${set.size} ${a + b}\")", opts: ["3 7", "2 7", "2 34", "1 7"], a: 1, why: "data class → equals/hashCode nach Inhalt: zwei gleiche P(1, 2) zählen im Set einmal. Destructuring: 3 + 4.", ex: "" },
 { id: "madb9", topic: "mad-gen", q: "Welcher Typ wird inferiert?", code: "fun <T, R> map(list: List<T>, fn: (T) -> R): List<R> = list.map(fn)\nval r = map(listOf(\"a\", \"bb\")) { it.length > 1 }", opts: ["List&lt;String&gt;", "List&lt;Int&gt;", "List&lt;Boolean&gt;", "Boolean"], a: 2, why: "T = String, R = Boolean (Ergebnis des Lambdas).", ex: "" },
 { id: "madb10", topic: "mad-err", q: "Was gibt der Code aus?", code: "fun check(x: Int): Int {\n    try {\n        require(x > 0) { \"neg\" }\n        return x\n    } catch (e: IllegalArgumentException) {\n        return -1\n    } finally {\n        print(\"F \")\n    }\n}\nprintln(check(-5) + check(5))", opts: ["F F 4", "4", "F 4", "F F -1"], a: 0, why: "finally läuft bei beiden Aufrufen (auch nach return); −1 + 5 = 4.", ex: "" }
